<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\User; use Pterodactyl\Models\Model; use Pterodactyl\Models\Server; use Illuminate\Database\Eloquent\Relations\BelongsTo; class AutoAction extends Model { public const RESOURCE_NAME = 'auto_action'; protected $table = 'dezerx_auto_actions'; protected $guarded = ['id']; protected $casts = [ 'server_id' => 'int', 'created_by' => 'int', 'attempts' => 'int', 'due_at' => 'datetime', 'processed_at' => 'datetime', ]; public static array $validationRules = [ 'server_id' => 'required|int|exists:servers,id', 'due_at' => 'required|date', 'action' => 'required|string', ]; public function isPending(): bool { return $this->processed_at === null; } public function server(): BelongsTo { return $this->belongsTo(Server::class); } public function author(): BelongsTo { return $this->belongsTo(User::class, 'created_by'); } } 